/// Un trazado de un icono de Reicon: si se rellena par-impar y sus órdenes
struct ReiconPart {
    let eo: Bool
    let d: String
}

/// (los trazados de cada icono, leídos una vez)
private var reiconCache: [String: [ReiconPart]] = [:]

/// Los trazados de un icono de Reicon (su nombre, sin «@90»); vacío si no está
func reiconParts(_ name: String) -> [ReiconPart] {
    if let c = reiconCache[name] { return c }
    let raw = REICON_PATHS[name] ?? ""
    var out: [ReiconPart] = []
    for piece in raw.components(separatedBy: "~") where piece.count > 2 {
        out.append(ReiconPart(eo: piece.hasPrefix("E|"), d: String(piece.dropFirst(2))))
    }
    reiconCache[name] = out
    return out
}

/// Un trazado de Reicon en su cuadrícula de 24, a la escala del recuadro (centrado, sin ajustarlo a su contorno:
/// todos los iconos llevan el mismo margen, como en Linux)
struct ReiconShape: Shape {
    let d: String
    func path(in rect: CGRect) -> Path {
        var p = Path()
        let t = d.split(separator: " ")
        var i = 0
        func num(_ k: Int) -> CGFloat {
            return i + k < t.count ? CGFloat(Double(t[i + k]) ?? 0) : 0
        }
        while i < t.count {
            let c = t[i]
            i += 1
            if c == "M" {
                p.move(to: CGPoint(x: num(0), y: num(1)))
                i += 2
            } else if c == "L" {
                p.addLine(to: CGPoint(x: num(0), y: num(1)))
                i += 2
            } else if c == "C" {
                p.addCurve(to: CGPoint(x: num(4), y: num(5)), control1: CGPoint(x: num(0), y: num(1)),
                           control2: CGPoint(x: num(2), y: num(3)))
                i += 6
            } else if c == "Z" {
                p.closeSubpath()
            }
        }
        let k = Swift.min(rect.width, rect.height) / 24
        let move = CGAffineTransform(translationX: rect.midX - 12 * k, y: rect.midY - 12 * k)
        return p.applying(move.scaledBy(x: k, y: k))
    }
}

/// Un icono de Reicon («nombre», «nombre!f» o «nombre@90») del color del primer plano (como un símbolo: lo hereda de
/// foregroundColor), en un cuadrado del lado dado
struct ReiconImage: View {
    let name: String
    let size: CGFloat

    var body: some View {
        let base = name.components(separatedBy: "@").first ?? name
        let turn = Double(name.components(separatedBy: "@").dropFirst().first ?? "0") ?? 0
        let parts = reiconParts(base)
        return ZStack {
            ForEach(parts.indices, id: \.self) { i in
                ReiconShape(d: parts[i].d).fill(style: FillStyle(eoFill: parts[i].eo))
            }
        }
        .frame(width: size, height: size)
        .rotationEffect(.degrees(turn))
    }
}

/// Un icono de la interfaz por su nombre de SF Symbol: el de Reicon que lo sustituye (REICON_FOR_SF), algo más grande
/// que la letra porque los de Reicon llevan margen, o, si no tiene, el propio símbolo con esa letra
struct UIIcon: View {
    let name: String
    let size: CGFloat
    let weight: Font.Weight

    init(_ name: String, size: CGFloat = 13, weight: Font.Weight = .regular) {
        self.name = name
        self.size = size
        self.weight = weight
    }

    var body: some View {
        if let r = REICON_FOR_SF[name] {
            ReiconImage(name: r, size: (size * 1.3).rounded())
        } else {
            Image(systemName: name).font(.system(size: size, weight: weight))
        }
    }
}

/// (las imágenes de plantilla ya hechas: nombre|lado)
private var reiconImages: [String: NSImage] = [:]

/// Un icono de Reicon en una imagen de plantilla (se pinta del color del texto), para donde SwiftUI solo admite
/// imágenes, como la etiqueta de un Menu
func reiconNSImage(_ name: String, size: CGFloat) -> NSImage? {
    let id = name + "|" + String(Int(size))
    if let i = reiconImages[id] { return i }
    let base = name.components(separatedBy: "@").first ?? name
    let turn = CGFloat(Double(name.components(separatedBy: "@").dropFirst().first ?? "0") ?? 0)
    let parts = reiconParts(base)
    if parts.isEmpty { return nil }
    let img = NSImage(size: NSSize(width: size, height: size), flipped: true) { rect in
        guard let ctx = NSGraphicsContext.current?.cgContext else { return false }
        let k = rect.width / 24
        ctx.translateBy(x: rect.midX, y: rect.midY)
        ctx.rotate(by: turn * .pi / 180)
        ctx.scaleBy(x: k, y: k)
        ctx.translateBy(x: -12, y: -12)
        ctx.setFillColor(NSColor.black.cgColor)
        for p in parts {
            let r = ReiconShape(d: p.d).path(in: CGRect(x: 0, y: 0, width: 24, height: 24))
            ctx.addPath(r.cgPath)
            ctx.fillPath(using: p.eo ? .evenOdd : .winding)
        }
        return true
    }
    img.isTemplate = true
    reiconImages[id] = img
    return img
}

/// Una imagen de un icono de la interfaz por su nombre de SF Symbol: la de Reicon (de plantilla) o el propio símbolo
func uiIconImage(_ sf: String, size: CGFloat) -> Image {
    if let r = REICON_FOR_SF[sf], let i = reiconNSImage(r, size: size) {
        return Image(nsImage: i).renderingMode(.template)
    }
    return Image(systemName: sf)
}

/// Un color de marca con su versión para el tema oscuro (los logotipos negros, como Symfony, se verían mal en él)
func dynamicHex(_ light: UInt32, _ dark: UInt32) -> Color {
    func ns(_ v: UInt32) -> NSColor {
        return NSColor(srgbRed: CGFloat((v >> 16) & 0xFF) / 255.0, green: CGFloat((v >> 8) & 0xFF) / 255.0,
                       blue: CGFloat(v & 0xFF) / 255.0, alpha: 1)
    }
    let l = ns(light), d = ns(dark)
    return Color(NSColor(name: nil, dynamicProvider: { a in
        a.bestMatch(from: [.darkAqua, .aqua]) == .darkAqua ? d : l
    }))
}

