// MARK: iconos en color (Apariencia, «Iconos en color»)

/// Con los iconos en color (Apariencia): lo pone ContentView y lo leen TintIcon y VisorIconView
struct IconsTintedKey: EnvironmentKey {
    static let defaultValue = false
}

extension EnvironmentValues {
    var iconsTinted: Bool {
        get { self[IconsTintedKey.self] }
        set { self[IconsTintedKey.self] = newValue }
    }
}

/// Los colores de los iconos de acción, por su función (como ICON_TINTS de Linux)
let ICON_TINT_COLORS: [String: UInt32] = ["verde": 0x2EA043, "rojo": 0xE5534B, "azul": 0x2F81F7, "naranja": 0xF0883E,
                                          "amarillo": 0xD4A300, "morado": 0xA371F7, "turquesa": 0x1F9E95]

/// El color de cada icono de acción (su nombre de SF Symbol o, los del visor, de Reicon)
let ICON_TINTS: [String: String] = {
    var m: [String: String] = [:]
    let groups: [(String, [String])] = [
        ("verde", ["play.fill", "play.circle", "checkmark.circle.fill", "plus", "folder.badge.plus"]),
        ("rojo", ["stop.fill", "stop.circle", "trash", "trash.fill", "xmark", "xmark.circle", "xmark.circle.fill",
                  "xmark.octagon.fill", "minus", "eject.fill", "link-broken", "logout"]),
        ("azul", ["arrow.clockwise", "arrow.triangle.2.circlepath", "arrow.down.circle", "arrow.down.circle.fill",
                  "arrow.up.circle", "square.and.arrow.up", "square.and.arrow.up.fill", "square.and.arrow.down",
                  "icloud.and.arrow.down", "chevron.up", "chevron.down", "upload", "refresh-circle"]),
        ("naranja", ["pencil", "sparkles", "arrow.uturn.backward"]),
        ("amarillo", ["key", "star", "star.fill", "exclamationmark.triangle", "exclamationmark.triangle.fill",
                      "exclamationmark.shield"]),
        ("morado", ["link", "globe", "network", "cloud", "antenna.radiowaves.left.and.right", "server.rack"]),
        ("turquesa", ["terminal", "terminal.fill", "doc.on.doc", "doc.on.doc.fill", "file-text", "code-file", "doc.text",
                      "doc.text.fill", "clock.arrow.circlepath", "cylinder.split.1x2", "externaldrive", "externaldrive.fill"]),
    ]
    for (tint, names) in groups {
        for n in names { m[n] = tint }
    }
    return m
}()

/// Los colores del logotipo de Nexum (para los iconos que no son de acción), como NEXUM_COLORS de Linux
let NEXUM_TINTS: [UInt32] = [0x006CB7, 0x88BB1D, 0xFFB608, 0xFF3B3B, 0xF20093]

/// (el color al azar de cada icono: el mismo mientras la ventana esté abierta)
private var nexumTints: [String: Int] = [:]

/// El color de un icono con los iconos en color: el de su función o, si no tiene, uno de los del logotipo de Nexum
func iconTint(_ name: String, dark: Bool) -> Color {
    if let t = ICON_TINTS[name], let v = ICON_TINT_COLORS[t] { return hexColor(v) }
    let n = nexumTints[name] ?? Int.random(in: 0..<NEXUM_TINTS.count)
    nexumTints[name] = n
    // (el azul, más claro con el tema oscuro)
    if n == 0 && dark { return hexColor(0x3D9BE0) }
    return hexColor(NEXUM_TINTS[n])
}

/// Un icono de un botón (UIIcon): con los iconos en color, del color de su función; si no, del de su texto
struct TintIcon: View {
    let name: String
    let size: CGFloat
    let weight: Font.Weight
    @Environment(\.iconsTinted) var tinted
    @Environment(\.colorScheme) var scheme

    init(_ name: String, size: CGFloat = 13, weight: Font.Weight = .regular) {
        self.name = name
        self.size = size
        self.weight = weight
    }

    var body: some View {
        UIIcon(name, size: size, weight: weight)
            .foregroundColor(tinted ? iconTint(name, dark: scheme == .dark) : nil)
    }
}

/// Los nombres que se acortan en un botón cuadrado si el entero no cabe debajo de su icono (SQUARE_SHORT_NAMES)
let SQUARE_SHORT_NAMES: [String: String] = ["phpMyAdmin": "PMA", "Imágenes de producción": "Imágenes"]

/// El nombre de un botón cuadrado: entero si cabe en avail puntos con esa letra y, si no, su forma corta, si tiene
func squareName(_ name: String, _ avail: CGFloat, _ fontSize: CGFloat) -> String {
    guard let short = SQUARE_SHORT_NAMES[name] else { return name }
    let w = (name as NSString).size(withAttributes: [.font: NSFont.systemFont(ofSize: fontSize)]).width
    return w > avail ? short : name
}
